@Component
public class DataInitializer implements CommandLineRunner {

    private final UserMapper userMapper;
    private final WorkspaceMapper workspaceMapper;
    private final NoteMapper noteMapper;
    private final String workspaceRoot;

    public DataInitializer(UserMapper userMapper,
                           WorkspaceMapper workspaceMapper,
                           NoteMapper noteMapper,
                           @Value("${notebox.workspace.root}") String workspaceRoot) {
        this.userMapper = userMapper;
        this.workspaceMapper = workspaceMapper;
        this.noteMapper = noteMapper;
        this.workspaceRoot = workspaceRoot;
    }

    @Override
    public void run(String... args) throws Exception {
        if (userMapper.count() > 0) {
            return;
        }

        LocalDateTime now = LocalDateTime.now();

        User admin = createUser("admin", "admin123", "ADMIN", now);
        User user1 = createUser("user1", "user123", "USER", now);
        User user2 = createUser("user2", "user456", "USER", now);

        Workspace ws1 = createWorkspace("个人笔记", "日常记录和思考", user1.getId(), now);
        Workspace ws2 = createWorkspace("项目文档", "项目相关文档", user1.getId(), now);
        Workspace ws3 = createWorkspace("学习资料", "技术学习笔记", user2.getId(), now);

        createNoteFile(ws1.getId(), "welcome.md", "欢迎", "# 欢迎使用 NoteBox\n\n这是你的第一篇笔记。", now);
        createNoteFile(ws2.getId(), "readme.md", "README", "# 项目文档\n\n在这里记录项目信息。", now);
        createNoteFile(ws3.getId(), "notes.md", "学习笔记", "# 学习笔记\n\n记录学习心得。", now);
    }

    private User createUser(String username, String password, String role, LocalDateTime now) {
        User user = new User();
        user.setUsername(username);
        user.setPassword(password);
        user.setRole(role);
        user.setCreatedAt(now);
        userMapper.insert(user);
        return user;
    }

    private Workspace createWorkspace(String name, String description, Long userId, LocalDateTime now) {
        Workspace ws = new Workspace();
        ws.setName(name);
        ws.setDescription(description);
        ws.setUserId(userId);
        ws.setCreatedAt(now);
        workspaceMapper.insert(ws);

        try {
            Files.createDirectories(Path.of(workspaceRoot, String.valueOf(ws.getId())));
        } catch (IOException e) {
            throw new RuntimeException("Failed to create workspace directory: " + ws.getId(), e);
        }

        return ws;
    }

